  variantId: string | null;
  itemName: string;
  variantName: string | null;
  sku: string;
  itemsSold: number;
  grossSales: number;
  itemsRefunded: number;
  refunds: number;
  discounts: number;
  netSales: number;
  costOfGoods: number;
  grossProfit: number;
  marginPercent: number;
  taxes: number;
};

type SalesByPaymentTypeRow = {
  paymentTypeId: string;
  name: string;
  type: string;
  paymentsReceived: number;
  refunds: number;
  netPayments: number;
};

type SalesByItemReport = {
  receiptCount: number;
  rows: SalesByItemRow[];
  paymentsByType: SalesByPaymentTypeRow[];
  totals: {
    itemsSold: number;
    grossSales: number;
    itemsRefunded: number;
    refunds: number;
