        dataIndex: "itemsSold",
        key: "itemsSold",
        align: "right",
        width: 110,
        render: formatNumber,
      },
      {
        title: "Refunded",
        dataIndex: "itemsRefunded",
        key: "itemsRefunded",
        align: "right",
        width: 120,
        render: formatNumber,
      },
      {
        title: "Gross",
        dataIndex: "grossSales",
        key: "grossSales",
        align: "right",
        width: 140,
        render: formatMoney,
      },
      {
        title: "Discounts",
        dataIndex: "discounts",
        key: "discounts",
        align: "right",
        width: 140,
        render: formatMoney,
      },
      {
        title: "Net",
        dataIndex: "netSales",
        key: "netSales",
        align: "right",
        width: 140,
        render: formatMoney,
      },
      {
        title: "Profit",
        dataIndex: "grossProfit",
        key: "grossProfit",
        align: "right",
        width: 140,
        render: formatMoney,
      },
      {
        title: "Margin",
        dataIndex: "marginPercent",
        key: "marginPercent",
        align: "right",
        width: 110,
        render: (value: number) => `${formatNumber(value)}%`,
