async function fetchJson<T>(
  path: string,
  signal?: AbortSignal,
  requestBody?: unknown,
): Promise<T> {
  const response = await fetch(path, {
    body: requestBody === undefined ? undefined : JSON.stringify(requestBody),
    headers:
      requestBody === undefined
        ? undefined
        : { "Content-Type": "application/json" },
    method: requestBody === undefined ? "GET" : "POST",
    signal,
  });
  const responseBody = (await response.json().catch(() => ({}))) as {
    error?: string;
  };
  if (!response.ok) {
    throw new Error(
      responseBody.error || `Request failed with status ${response.status}.`,
    );
  }
  return responseBody as T;
}

function isBeforeBangkokSyncCutoff(): boolean {
  const parts = new Intl.DateTimeFormat("en-US", {
    hour: "2-digit",
    hour12: false,
    minute: "2-digit",
    timeZone: "Asia/Bangkok",
  }).formatToParts(new Date());
  const hour = Number(parts.find((part) => part.type === "hour")?.value || 0);
  const minute = Number(
    parts.find((part) => part.type === "minute")?.value || 0,
  );
  return hour * 60 + minute < 20 * 60 + 30;
}

function getBangkokDate(date: Date): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    day: "2-digit",
    month: "2-digit",
    timeZone: "Asia/Bangkok",
    year: "numeric",
  }).formatToParts(date);
  const year = parts.find((part) => part.type === "year")?.value || "";
  const month = parts.find((part) => part.type === "month")?.value || "";
  const day = parts.find((part) => part.type === "day")?.value || "";
  return `${year}-${month}-${day}`;
}

function formatMoney(value: number): string {
  return THB_FORMATTER.format(value);
}

function formatNumber(value: number): string {
  return NUMBER_FORMATTER.format(value);
}

function getPickerValue(value: string | string[] | null): string {
  return Array.isArray(value) ? value[0] || "" : value || "";
}

function shiftDate(value: string, days: number): string {
  return dayjs(value, "YYYY-MM-DD").add(days, "day").format("YYYY-MM-DD");
}

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

